import{z as s,x as l,o as A,c as n,q as B,j as r,D as a,d as i,s as t,S as o}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Lagos–Wright 新货币主义","description":"","frontmatter":{"title":"Lagos–Wright 新货币主义","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lagos-wright.md","filePath":"econ/lagos-wright.md","lastUpdated":1791413859000}'),p={name:"econ/lagos-wright.md"};function C(d,E,D,h,M,m){const e=l("Mermaid");return A(),n("div",null,[E[2]||(E[2]=B('<h1 id="lagos–wright-新货币主义" tabindex="-1">Lagos–Wright 新货币主义 <a class="header-anchor" href="#lagos–wright-新货币主义" aria-label="Permalink to &quot;Lagos–Wright 新货币主义&quot;">​</a></h1><div class="epigraph"><p>货币有价值，是因为分散配对里缺少记录与信用；把集中市场定期打开，只是为了让模型能算，不是又把货币塞进效用。</p><footer>—— Lagos and Wright, A Unified Framework for Monetary Theory and Policy Analysis, JPE 2005</footer></div><p><a href="/econ/cia-miu">上一课</a>用现金先行或货币入效用，让家庭愿意持有不生息的 \\(M\\)，并声明搜寻匹配是第三条微观。本课的缺口是把第三条写完：在匿名、配对、缺乏公开记录的交易里，货币作为记忆的替代成为必要。Lagos–Wright（2005）用集中市场（CM）与分散市场（DM）交替，使分布可处理。数量方程下一课才把 \\(P\\) 接到 \\(y\\)；本课只换装置。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CIA 把「必须先有现金」写进约束，MIU 把 \\(m\\) 写进 \\(u\\)。二者都能给出货币需求，但货币为何被接受，仍是假设。Kiyotaki–Wright 一类搜寻已经说明：没有记录时，物物交换的需求双重巧合失败，货币可以作为媒介。缺口是：如何在保留配对摩擦的同时，得到可分析的分布与政策比较。LW 的回答：夜间 CM 里瓦尔拉斯出清、准线性偏好把货币分布重新洗平；日间 DM 里随机配对、议价，货币转手。</p><p><span class="marginnote">术语翻译：需求双重巧合就是「我有的恰好是你想要的，你有的也恰好是我想要的」。渔夫有鱼想换面包，面包师却不吃鱼——两人只能擦肩而过。货币的价值正在于此：交易不再需要双方需求恰好互补，先换成代币，各自再找想要的。</span></p><p><span class="marginnote">「新货币主义」在此指 Lagos–Wright 及其后的配对货币模型，不是货币主义数量论的口号。数量论的会计下一课再写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一期分两个子市场。DM：买卖双方配对，可能用货币交换货物，条件是对方接受；议价决定数量与价格（或条款）。CM：劳动、货物与货币一次性出清，清偿 DM 留下的余额。准线性使 CM 里货币需求与财富线性，次日进入 DM 的人持币量相同——这是技术，为了避开无限维分布。货币均衡：若预期他人接受，自己也持有并接受；预期崩溃则回到物物或自给。</p>',9)),(A(),r(o,null,{default:a(()=>[t(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CIA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%E7%BA%A6%E6%9D%9F%E6%88%96%E6%95%88%E7%94%A8%E9%87%8C%E7%9A%84%20M%22%5D%20--%3E%20LW%5B%22%E9%85%8D%E5%AF%B9%EF%BC%9A%E8%B4%A7%E5%B8%81%E5%BD%93%E8%AE%B0%E5%BF%86%22%5D%0A%20%20DM%5B%22%E5%88%86%E6%95%A3%E9%85%8D%E5%AF%B9%20DM%22%5D%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%E4%B8%8E%E8%AE%AE%E4%BB%B7%22%5D%0A%20%20CM%5B%22%E9%9B%86%E4%B8%AD%E5%B8%82%E5%9C%BA%20CM%22%5D%20--%3E%20DIST%5B%22%E5%88%86%E5%B8%83%E8%A2%AB%E6%B4%97%E5%B9%B3%22%5D%0A%20%20ACC%20--%3E%20VAL%5B%22%E8%B4%A7%E5%B8%81%E6%9C%89%E4%BB%B7%E5%80%BC%22%5D%0A%20%20DIST%20--%3E%20VAL%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p>最优持币仍对名义利率敏感：通胀税侵蚀 DM 里的购买力，类似 CIA 的扭曲，但来自配对条款而不是 Clower 不等式。Friedman 规则在许多 LW 校准里仍指向 \\(i=0\\)，因为持币的社会成本接近零。本课不宣布最优通胀的点估计。</p><h3 id="不是把-miu-换记号" tabindex="-1">不是把 MIU 换记号 <a class="header-anchor" href="#不是把-miu-换记号" aria-label="Permalink to &quot;不是把 MIU 换记号&quot;">​</a></h3><p>\\(u(c,m)\\) 里 \\(m\\) 的服务是被假定的。LW 的服务来自 DM 里否则无法成交的交易。把 LW 的 CM 效用写成 \\(u(c)+v(m)\\) 再当 MIU 用，会把配对摩擦洗掉。装置声明必须保留 DM。</p><h3 id="接受是均衡-不是法定" tabindex="-1">接受是均衡，不是法定 <a class="header-anchor" href="#接受是均衡-不是法定" aria-label="Permalink to &quot;接受是均衡，不是法定&quot;">​</a></h3><p>法币被接受，因为别人预期它能在 CM 或下一次 DM 换到货。若预期崩溃，法定支付能力也救不回配对成交——除非惩罚足够硬，那已是另一套强制。</p><p><span class="marginnote">常见误区：初学者容易以为「法币有政府背书，所以必然被接受」。在配对模型里，接受是每个人的策略选择：若人人预期别人会拒收，法币立刻退回物物交换——历史上恶性通胀中「以物易物」的回归就是预期崩溃的版本。</span></p><p>本课保持自愿接受的货币均衡，以便通胀税仍通过条款起作用，而不是通过法律条文。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>匿名配对切断信用：对方下次不一定遇见你，公开记录又不存在，于是需要可携带的代币。接受是策略：人人预期货币可换到 CM 或下一次 DM 的货，代币就有正价格。通胀提高持币成本，DM 成交量下降——货币不是面纱，通道是配对条件而不是 Sidrauski 的超中性特例。内部货币（银行债务）可以部分替代代币，一旦记录改善；本课保持外生法币，以免提前写成中介。</p>',9)),(A(),r(o,null,{default:a(()=>[t(e,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22DM%20%E4%B8%AD%E4%B9%B0%E5%8D%96%E5%8F%8C%E6%96%B9%E7%9B%B8%E9%81%87%22%5D%20--%3E%20R%7B%22%E6%9C%89%E6%97%A0%E5%85%AC%E5%BC%80%E8%AE%B0%E5%BD%95%E6%88%96%E4%BF%A1%E7%94%A8%22%7D%0A%20%20R%20--%20%22%E6%97%A0%E8%AE%B0%E5%BD%95%EF%BC%8C%E8%B5%8A%E8%B4%A6%E6%97%A0%E4%BB%8E%E8%BF%BD%E8%AE%A8%22%20--%3E%20T%5B%22%E9%9C%80%E8%A6%81%E5%8F%AF%E6%90%BA%E5%B8%A6%E7%9A%84%E4%BB%A3%E5%B8%81%22%5D%0A%20%20R%20--%20%22%E8%AE%B0%E5%BD%95%E8%89%AF%E5%A5%BD%EF%BC%8C%E5%8F%AF%E7%94%A8%E5%80%BA%E5%8A%A1%E6%9B%BF%E4%BB%A3%22%20--%3E%20D%5B%22%E8%B5%8A%E9%94%80%E6%88%90%E4%BA%A4%EF%BC%8C%E8%B4%A7%E5%B8%81%E8%A2%AB%E7%BB%95%E5%BC%80%22%5D%0A%20%20T%20--%3E%20A%7B%22%E5%8D%96%E6%96%B9%E9%A2%84%E6%9C%9F%E4%BB%A3%E5%B8%81%E4%B8%8B%E6%9C%9F%E8%83%BD%E6%8D%A2%E5%88%B0%E8%B4%A7%E5%90%97%22%7D%0A%20%20A%20--%20%22%E4%BA%BA%E4%BA%BA%E9%A2%84%E6%9C%9F%E5%88%AB%E4%BA%BA%E6%8E%A5%E5%8F%97%22%20--%3E%20Y%5B%22%E6%8E%A5%E5%8F%97%E8%B4%A7%E5%B8%81%EF%BC%8C%E6%88%90%E4%BA%A4%22%5D%0A%20%20A%20--%20%22%E9%A2%84%E6%9C%9F%E5%B4%A9%E6%BA%83%EF%BC%8C%E4%BA%BA%E4%BA%BA%E6%8B%92%E6%94%B6%22%20--%3E%20N%5B%22%E5%9B%9E%E5%88%B0%E7%89%A9%E7%89%A9%E6%88%96%E8%87%AA%E7%BB%99%22%5D%0A%20%20Y%20--%3E%20INF%5B%22%E9%80%9A%E8%83%80%E6%8A%AC%E9%AB%98%E6%8C%81%E5%B8%81%E6%88%90%E6%9C%AC%EF%BC%8C%E6%88%90%E4%BA%A4%E6%9D%A1%E6%AC%BE%E5%8F%98%E5%B7%AE%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p>CIA 的硬约束给出速度上限；LW 的速度来自配对频率与议价条款，通胀通过条款变松，而不是 Clower 不等式突然不绑定。MIU 的 \\(u_m\\) 在 LW 里被 DM 的边际成交量替代：持币的私人收益是多成交或更好条款。把三种装置校准到同一货币需求弹性之后，超中性与福利仍可分叉——装置选择不是无害记号，上一课已经对 CIA/MIU 说过，配对是同一警告的第三条。</p><p><span class="marginnote">数字实例（通胀税）：你口袋里揣着 100 元，一年通胀 \\(3\\%\\)，年末这 100 元只能买到年初 \\(97\\) 元的东西——差的 \\(3\\) 元没人开收据，却是实实在在征走的「税」。持币越多、持得越久，交得越多，于是人们减少持币，DM 里靠现金成交的买卖跟着萎缩。</span></p><p>开放配对与外汇是另一层。CIP 作为市场层无套利，实证在<a href="/quant/irp">量化栏</a>，不在本课的 DM 议价里估基差。</p><p><span class="marginnote">CM 的准线性是为了可解，不是声称夜间真的有完美保险。放松它，持币分布进入状态，政策比较立刻变重。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准配对概率，不把 LW 写成支付系统工程。CIA/MIU 在宏观主干里仍常用，因为三方程要的是货币需求弹性，不是配对。后课数量论把 \\(MV=Py\\) 当会计与长期中性；LW 提供「\\(M\\) 为何在 \\(V\\) 里出现」的微观之一。也不要把搜寻劳动（DMP）与搜寻货币焊成同一个匹配函数——对象不同。</p><p>信贷记录一旦变好，DM 可以用债务替代代币，货币必要性下降——这是内部货币与中介课的接头，本课故意关掉。把电子支付写成「因此 LW 过时」，忽略了匿名与缺乏承诺仍在的角落。装置要声明记录技术，不能用支付 App 的界面替代配对摩擦。</p><p>后课默认：需要货币微观时，除约束与效用外，可以声明配对接受。下一课：无论哪一种微观，长期 \\(P\\) 与 \\(M\\) 如何对齐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CIA/MIU 假定持币理由；LW 从匿名配对推出货币必要。</li><li>DM 成交、CM 洗分布，是为了可分析，不是把 \\(m\\) 塞回效用。</li><li>通胀税扭曲 DM 条款；接受是均衡策略。</li><li>CIP 实证不在配对议价里，见 <code>/quant/irp</code>。</li><li>出处：Lagos and Wright, <em>JPE</em> 2005；Kiyotaki–Wright 搜寻货币为先声。</li></ul>',10))])}const _=s(p,[["render",C]]);export{g as __pageData,_ as default};
